reference_solution:
def nth_magical_number(n,a,b):
    from math import gcd
    common=a//gcd(a,b)*b;left,right=1,n*min(a,b)
    while left<right:
        middle=(left+right)//2
        if middle//a+middle//b-middle//common>=n:right=middle
        else:left=middle+1
    return left%(10**9+7)

